    c = conn.cursor()

    # Clear existing data
    c.execute('DELETE FROM business_metrics')
    c.execute('DELETE FROM projects')
    c.execute('DELETE FROM approvals')
    c.execute('DELETE FROM notifications')

    # Business metrics
    metrics = [
        ('Books', 'Manuscript Words', 150000, 'words', '2024-01-15 10:00:00', 200000),
        ('Books', 'Chapters Completed', 45, 'chapters', '2024-01-15 10:00:00', 64),
        ('Books', 'Books Published', 2, 'books', '2024-01-15 10:00:00', 4),
        ('SaaS', 'Active Users', 1250, 'users', '2024-01-15 10:00:00', 5000),
        ('SaaS', 'Server Uptime', 99.8, '%', '2024-01-15 10:00:00', 99.9),
        ('SaaS', 'New Signups', 45, 'users', '2024-01-15 10:00:00', 100),
