        ('Consulting', 'Deliverables This Month', 23, 'deliverables', '2024-01-15 10:00:00', 30),
    ]

    c.executemany('INSERT INTO business_metrics (business_line, metric_name, value, unit, updated_at, target) VALUES (?, ?, ?, ?, ?, ?)', metrics)

    # Projects
    projects = [
        ('First Generation Book', 'Books', 'In Progress', 75, '2024-03-01', 'High', '2024-01-15 10:00:00'),
        ('Second Generation Book', 'Books', 'In Progress', 60, '2024-04-15', 'High', '2024-01-15 10:00:00'),
        ('The Future is Unwritten', 'Books', 'Planning', 25, '2024-06-01', 'Medium', '2024-01-15 10:00:00'),
        ('Small Business AI Book', 'Books', 'In Progress', 40, '2024-05-15', 'Medium', '2024-01-15 10:00:00'),
        ('Hermes Agent Platform', 'SaaS', 'In Progress', 85, '2024-02-28', 'Critical', '2024-01-15 10:00:00'),
        ('MemPalace Integration', 'SaaS', 'Testing', 70, '2024-03-15', 'High', '2024-01-15 10:00:00'),
        ('OpenClaw Development', 'SaaS', 'Planning', 30, '2024-06-01', 'High', '2024-01-15 10:00:00'),
        ('Client A - AI Integration', 'Consulting', 'Completed', 100, '2024-01-20', 'High', '2024-01-15 10:00:00'),
        ('Client B - Process Automation', 'Consulting', 'In Progress', 65, '2024-02-15', 'Medium', '2024-01-15 10:00:00'),
        ('Client C - Data Analysis', 'Consulting', 'In Progress', 40, '2024-03-01', 'Medium', '2024-01-15 10:00:00'),
    ]

    c.executemany('INSERT INTO projects (project_name, business_line, status, progress, deadline, priority, last_updated) VALUES (?, ?, ?, ?, ?, ?, ?)', projects)

    # Approvals
    approvals = [
        ('Book Cover', 'First Generation Cover', 1, 'Pending', 'Robert Mills', '2024-01-15 09:30:00', None, None, 'Review design'),
