    if status and progress:
        c.execute('''UPDATE projects 
                     SET status = ?, progress = ?, last_updated = datetime('now')
                     WHERE id = ?''', (status, progress, project_id))
    elif status:
        c.execute('''UPDATE projects 
                     SET status = ?, last_updated = datetime('now')
                     WHERE id = ?''', (status, project_id))
    elif progress:
