                'Books': [],
                'SaaS': [],
                'Consulting': []
            };

            metrics.forEach(metric => {
                metricCategories[metric.business_line].push(metric);
            });

            for (const [category, categoryMetrics] of Object.entries(metricCategories)) {
                if (categoryMetrics.length > 0) {
                    metricsHTML += `
                        <div class="card">
                            <div class="card-header">
                                <div class="card-title">${category} Metrics</div>
                            </div>
                            <div class="card-body">
                                <div class="grid">
                    `;

                    categoryMetrics.forEach(metric => {
                        const progress = (metric.value / metric.target) * 100;
                        const progressColor = progress >= 100 ? 'var(--success-color)' : 'var(--primary-color)';

                        metricsHTML += `
                            <div class="metric-card">
                                <div class="metric-label">${metric.metric_name}</div>
                                <div class="metric-value">${metric.value} ${metric.unit}</div>
                                <div class="metric-target">Target: ${metric.target} ${metric.unit}</div>
