                                </div>
                                <div class="approval-actions">
                                    <button class="btn btn-success" onclick="openApprovalModal(${approval.id})">
                                        <i class="fas fa-check"></i> Approve
                                    </button>
                                    <button class="btn btn-danger" onclick="openApprovalModal(${approval.id}, true)">
                                        <i class="fas fa-times"></i> Reject
                                    </button>
                                </div>
                            </div>
                        </div>
                    `;
                });
            }

            document.getElementById('content-area').innerHTML = `
                <div class="grid">
                    ${approvalsHTML}
                </div>
            `;
        }

        function renderNotifications(data) {
            const notifications = data.notifications || [];

            let notificationsHTML = '';
            if (notifications.length === 0) {
                notificationsHTML = '<p>No notifications.</p>';
            } else {
                notifications.forEach(notification => {
                    const unreadClass = notification.read ? '' : 'unread';
                    notificationsHTML += `
                        <div class="notification-item ${unreadClass}">
                            <i class="fas fa-${notification.type === 'warning' ? 'exclamation-triangle' : 'info-circle'} notification-icon"></i>
                            <div class="notification-content">
                                <div class="notification-title">${notification.title}</div>
                                <div class="notification-message">${notification.message}</div>
                                <div class="notification-time">${new Date(notification.timestamp).toLocaleString()}</div>
                            </div>
                        </div>
                    `;
                });
            }

            document.getElementById('content-area').innerHTML = `
                <div class="grid">
                    <div class="card">
                        <div class="card-header">
                            <div class="card-title">All Notifications</div>
                        </div>
                        <div class="card-body">
                            ${notificationsHTML}
                        </div>
                    </div>
                </div>
            `;
        }

        function refreshData() {
            loadView(currentView);
        }

        function openApprovalModal(approvalId, isReject = false) {
            fetch(`/api/approvals/${approvalId}`)
                .then(response => response.json())
                .then(approval => {
                    document.getElementById('approvalId').value = approvalId;
                    document.getElementById('artifactType').value = approval.artifact_type;
                    document.getElementById('artifactName').value = approval.artifact_name;
                    document.getElementById('approvalNotes').value = '';

                    const modal = document.getElementById('approvalModal');
                    modal.style.display = 'flex';

                    if (isReject) {
                        // Switch to reject mode
                        document.querySelector('.modal-footer').innerHTML = `
                            <button class="btn" onclick="closeApprovalModal()">Cancel</button>
                            <button class="btn btn-danger" onclick="submitRejection()">Reject</button>
                        `;
                    }
                });
        }

        function closeApprovalModal() {
            document.getElementById('approvalModal').style.display = 'none';
        }

        function submitApproval() {
            const approvalId = document.getElementById('approvalId').value;
            const notes = document.getElementById('approvalNotes').value;

            fetch(`/api/approve/${approvalId}`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ notes: notes })
            })
            .then(response => response.json())
            .then(data => {
                if (data.status === 'success') {
                    closeApprovalModal();
                    refreshData();
                    alert('Artifact approved successfully!');
                }
            });
        }

        function submitRejection() {
            const approvalId = document.getElementById('approvalId').value;
            const notes = document.getElementById('approvalNotes').value;

            fetch(`/api/reject/${approvalId}`, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ notes: notes })
            })
            .then(response => response.json())
            .then(data => {
                if (data.status === 'success') {
                    closeApprovalModal();
                    refreshData();
                    alert('Artifact rejected successfully!');
                }
            });
        }

        function openUpdateProjectModal(projectId) {
            const progress = prompt('Enter new progress percentage (0-100):');
            if (progress && !isNaN(progress) && progress >= 0 && progress <= 100) {
                fetch(`/api/update_project/${projectId}`, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({ progress: parseFloat(progress) })
                })
                .then(response => response.json())
                .then(data => {
                    if (data.status === 'success') {
                        refreshData();
                        alert('Project updated successfully!');
                    }
                });
            } else if (progress !== null) {
                alert('Please enter a valid percentage (0-100).');
            }
        }
    </script>
</body>
</html>
