                    if (view === 'dashboard') {
                        renderDashboard(data);
                    } else if (view === 'projects') {
                        renderProjects(data);
                    } else if (view === 'approvals') {
                        renderApprovals(data);
                    } else if (view === 'notifications') {
                        renderNotifications(data);
                    } else {
                        contentArea.innerHTML = '<div class="loading">Loading...</div>';
