def init_db():
    conn = sqlite3.connect('mifeco_dashboard.db')
    c = conn.cursor()
    c.execute("CREATE TABLE IF NOT EXISTS business_metrics (id INTEGER PRIMARY KEY, business_line TEXT, metric_name TEXT, value REAL, unit TEXT, updated_at TIMESTAMP, target REAL)")
    c.execute("CREATE TABLE IF NOT EXISTS projects (id INTEGER PRIMARY KEY, project_name TEXT, business_line TEXT, status TEXT, progress REAL, deadline TEXT, priority TEXT, last_updated TIMESTAMP)")
    c.execute("CREATE TABLE IF NOT EXISTS approvals (id INTEGER PRIMARY KEY, artifact_type TEXT, artifact_name TEXT, project_id INTEGER, status TEXT, requested_by TEXT, requested_at TIMESTAMP, approved_by TEXT, approved_at TIMESTAMP, notes TEXT)")
    c.execute("CREATE TABLE IF NOT EXISTS notifications (id INTEGER PRIMARY KEY, title TEXT, message TEXT, type TEXT, timestamp TIMESTAMP, read BOOLEAN DEFAULT 0)")
    conn.commit()
    conn.close()

init_db()

