def update_dashboard_data():
    while True:
        try:
            conn = sqlite3.connect('mifeco_dashboard.db')
            c = conn.cursor()
            now = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
            manuscript_path = "/home/bob/books/Second_Generation/SECOND_GENERATION_COMPLETE.md"
            if os.path.exists(manuscript_path):
                try:
                    with open(manuscript_path, "r") as f:
                        lines = f.readlines()
                        word_count = sum(len(line.split()) for line in lines)
                        c.execute("UPDATE business_metrics SET value = ?, updated_at = ? WHERE metric_name = 'Manuscript Words' AND business_line = 'Books'", (word_count, now))
                except Exception as e:
                    print(f"Error reading manuscript: {e}")
            conn.commit()
            conn.close()
        except Exception as e:
            print(f"Error updating dashboard data: {e}")
        time.sleep(60)

thread = threading.Thread(target=update_dashboard_data, daemon=True)
thread.start()

@app.route("/")
def index():
    return render_template("dashboard.html")

@app.route("/api/metrics")
def get_metrics():
    conn = sqlite3.connect("mifeco_dashboard.db")
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    c.execute("SELECT * FROM business_metrics ORDER BY business_line, metric_name")
    metrics = [dict(row) for row in c.fetchall()]
    conn.close()
    return jsonify(metrics)

@app.route("/api/projects")
def get_projects():
    conn = sqlite3.connect("mifeco_dashboard.db")
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    c.execute("SELECT * FROM projects ORDER BY priority DESC, deadline")
    projects = [dict(row) for row in c.fetchall()]
    conn.close()
    return jsonify(projects)

@app.route("/api/approvals")
def get_approvals():
    conn = sqlite3.connect("mifeco_dashboard.db")
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    c.execute("SELECT * FROM approvals WHERE status = 'Pending' ORDER BY requested_at")
    approvals = [dict(row) for row in c.fetchall()]
    conn.close()
    return jsonify(approvals)

@app.route("/api/notifications")
def get_notifications():
    conn = sqlite3.connect("mifeco_dashboard.db")
    conn.row_factory = sqlite3.Row
    c = conn.cursor()
    c.execute("SELECT * FROM notifications ORDER BY timestamp DESC")
    notifications = [dict(row) for row in c.fetchall()]
    conn.close()
    return jsonify(notifications)

@app.route("/api/approve/<int:approval_id>", methods=["POST"])
def approve_artifact(approval_id):
    data = request.json
    notes = data.get("notes", "")
    conn = sqlite3.connect("mifeco_dashboard.db")
    c = conn.cursor()
    c.execute("UPDATE approvals SET status = 'Approved', approved_by = 'Robert Mills', approved_at = datetime('now'), notes = ? WHERE id = ?", (notes, approval_id))
    conn.commit()
    conn.close()
    return jsonify({"status": "success", "message": "Artifact approved"})

@app.route("/api/reject/<int:approval_id>", methods=["POST"])
def reject_artifact(approval_id):
    data = request.json
    notes = data.get("notes", "")
    conn = sqlite3.connect("mifeco_dashboard.db")
    c = conn.cursor()
    c.execute("UPDATE approvals SET status = 'Rejected', approved_by = 'Robert Mills', approved_at = datetime('now'), notes = ? WHERE id = ?", (notes, approval_id))
    conn.commit()
    conn.close()
    return jsonify({"status": "success", "message": "Artifact rejected"})

@app.route("/api/update_project/<int:project_id>", methods=["POST"])
def update_project(project_id):
    data = request.json
    status = data.get("status")
    progress = data.get("progress")
    conn = sqlite3.connect("mifeco_dashboard.db")
    c = conn.cursor()
    if status and progress:
        c.execute("UPDATE projects SET status = ?, progress = ?, last_updated = datetime('now') WHERE id = ?", (status, progress, project_id))
    elif status:
        c.execute("UPDATE projects SET status = ?, last_updated = datetime('now') WHERE id = ?", (status, project_id))
    elif progress:
        c.execute("UPDATE projects SET progress = ?, last_updated = datetime('now') WHERE id = ?", (progress, project_id))
    conn.commit()
    conn.close()
    return jsonify({"status": "success", "message": "Project updated"})

if __name__ == "__main__":
