        function updateActiveLink(view) {
            document.querySelectorAll('.nav-link').forEach(link => {
                link.classList.remove('active');
                if (link.getAttribute('data-view') === view) {
                    link.classList.add('active');
                }
            });
        }

        function loadView(view) {
            currentView = view;
            const contentArea = document.getElementById('content-area');

            contentArea.innerHTML = '<div class="loading">Loading...</div>';

            fetch('/api/' + view)
                .then(response => response.json())
                .then(data => {
                    if (view === 'dashboard') {
                        renderDashboard(data);
                    } else if (view === 'projects') {
                        renderProjects(data);
                    } else if (view === 'approvals') {
                        renderApprovals(data);
                    } else if (view === 'notifications') {
                        renderNotifications(data);
                    } else {
                        contentArea.innerHTML = '<div class="loading">Loading...</div>';
                    }
                })
                .catch(error => {
                    console.error('Error loading view:', error);
                    contentArea.innerHTML = '<div class="error">Error loading content</div>';
                });
        }

        function renderDashboard(data) {
            const metrics = data.metrics;
            const notifications = data.notifications || [];

            let metricsHTML = '';
            const metricCategories = {
                'Books': [],
                'SaaS': [],
                'Consulting': []
            };

            metrics.forEach(metric => {
                metricCategories[metric.business_line].push(metric);
            });

            for (const [category, categoryMetrics] of Object.entries(metricCategories)) {
                if (categoryMetrics.length > 0) {
                    metricsHTML += `
                        <div class="card">
                            <div class="card-header">
                                <div class="card-title">${category} Metrics</div>
                            </div>
                            <div class="card-body">
                                <div class="grid">
                    `;

                    categoryMetrics.forEach(metric => {
                        const progress = (metric.value / metric.target) * 100;
                        const progressColor = progress >= 100 ? 'var(--success-color)' : 'var(--primary-color)';

                        metricsHTML += `
                            <div class="metric-card">
                                <div class="metric-label">${metric.metric_name}</div>
                                <div class="metric-value">${metric.value} ${metric.unit}</div>
                                <div class="metric-target">Target: ${metric.target} ${metric.unit}</div>
                                <div class="progress-bar">
                                    <div class="progress-fill" style="width: ${progress}%; background-color: ${progressColor}"></div>
                                </div>
                            </div>
                        `;
                    });

                    metricsHTML += `
                                </div>
                            </div>
                        </div>
                    `;
                }
            }

            let notificationsHTML = '';
            if (notifications.length > 0) {
                notificationsHTML = `
                    <div class="card">
                        <div class="card-header">
                            <div class="card-title">Recent Notifications</div>
                            <span class="notification-badge">${notifications.length}</span>
                        </div>
                        <div class="card-body">
                            <div class="notification-list">
                `;

                notifications.forEach(notification => {
                    const unreadClass = notification.read ? '' : 'unread';
                    notificationsHTML += `
                        <div class="notification-item ${unreadClass}">
                            <i class="fas fa-${notification.type === 'warning' ? 'exclamation-triangle' : 'info-circle'} notification-icon"></i>
                            <div class="notification-content">
                                <div class="notification-title">${notification.title}</div>
                                <div class="notification-message">${notification.message}</div>
                                <div class="notification-time">${new Date(notification.timestamp).toLocaleString()}</div>
                            </div>
                        </div>
                    `;
                });

                notificationsHTML += `
                            </div>
                        </div>
                    </div>
                `;
            }

            const content = `
                <div class="grid">
                    ${metricsHTML}
                </div>
                <div class="grid">
                    ${notificationsHTML}
                </div>
            `;

            document.getElementById('content-area').innerHTML = content;
        }

        function renderProjects(data) {
            const projects = data.projects || [];

            let projectsHTML = '';
            if (projects.length === 0) {
                projectsHTML = '<p>No projects found.</p>';
            } else {
                projects.forEach(project => {
                    let priorityColor = 'var(--success-color)';
                    if (project.priority === 'High') priorityColor = 'var(--danger-color)';
                    else if (project.priority === 'Medium') priorityColor = 'var(--warning-color)';

                    projectsHTML += `
                        <div class="card project-card ${project.priority.toLowerCase()}">
                            <div class="card-header">
                                <div class="card-title">${project.project_name}</div>
                                <div class="project-deadline">Deadline: ${project.deadline}</div>
                            </div>
                            <div class="card-body">
                                <div class="project-header">
                                    <div>${project.business_line}</div>
                                    <div>${project.status}</div>
                                </div>
                                <div class="project-progress">
                                    <div class="progress-bar">
                                        <div class="progress-fill" style="width: ${project.progress}%"></div>
                                    </div>
                                    <div style="text-align: center; margin-top: 5px; font-size: 12px;">
                                        ${project.progress}% Complete
                                    </div>
                                </div>
                                <div class="approval-actions" style="justify-content: flex-end; margin-top: 15px;">
                                    <button class="btn btn-primary" onclick="openUpdateProjectModal(${project.id})">
                                        <i class="fas fa-edit"></i> Update
                                    </button>
                                </div>
                            </div>
                        </div>
                    `;
                });
            }

            document.getElementById('content-area').innerHTML = `
                <div class="grid">
                    ${projectsHTML}
                </div>
            `;
        }

        function renderApprovals(data) {
            const approvals = data.approvals || [];

            let approvalsHTML = '';
            if (approvals.length === 0) {
                approvalsHTML = '<p>No pending approvals.</p>';
            } else {
                approvals.forEach(approval => {
                    approvalsHTML += `
                        <div class="card approval-card">
                            <div class="card-header">
                                <div class="card-title">${approval.artifact_type}: ${approval.artifact_name}</div>
                            </div>
                            <div class="card-body">
                                <div style="margin-bottom: 10px;">
                                    <strong>Requested by:</strong> ${approval.requested_by}<br>
                                    <strong>Requested at:</strong> ${new Date(approval.requested_at).toLocaleString()}
                                </div>
                                <div class="approval-actions">
                                    <button class="btn btn-success" onclick="openApprovalModal(${approval.id})">
                                        <i class="fas fa-check"></i> Approve
                                    </button>
                                    <button class="btn btn-danger" onclick="openApprovalModal(${approval.id}, true)">
                                        <i class="fas fa-times"></i> Reject
                                    </button>
                                </div>
                            </div>
                        </div>
                    `;
                });
            }

            document.getElementById('content-area').innerHTML = `
                <div class="grid">
                    ${approvalsHTML}
                </div>
            `;
        }

        function renderNotifications(data) {
            const notifications = data.notifications || [];

            let notificationsHTML = '';
            if (notifications.length === 0) {
                notificationsHTML = '<p>No notifications.</p>';
            } else {
                notifications.forEach(notification => {
                    const unreadClass = notification.read ? '' : 'unread';
                    notificationsHTML += `
                        <div class="notification-item ${unreadClass}">
                            <i class="fas fa-${notification.type === 'warning' ? 'exclamation-triangle' : 'info-circle'} notification-icon"></i>
                            <div class="notification-content">
                                <div class="notification-title">${notification.title}</div>
                                <div class="notification-message">${notification.message}</div>
                                <div class="notification-time">${new Date(notification.timestamp).toLocaleString()}</div>
                            </div>
                        </div>
                    `;
                });
            }

            document.getElementById('content-area').innerHTML = `
                <div class="grid">
                    <div class="card">
                        <div class="card-header">
                            <div class="card-title">All Notifications</div>
                        </div>
                        <div class="card-body">
                            ${notificationsHTML}
                        </div>
                    </div>
                </div>
            `;
        }

        function refreshData() {
            loadView(currentView);
        }

        function openApprovalModal(approvalId, isReject = false) {
            fetch('/api/approvals/' + approvalId)
                .then(response => response.json())
                .then(approval => {
                    document.getElementById('approvalId').value = approvalId;
                    document.getElementById('artifactType').value = approval.artifact_type;
                    document.getElementById('artifactName').value = approval.artifact_name;
                    document.getElementById('approvalNotes').value = '';

                    const modal = document.getElementById('approvalModal');
                    modal.style.display = 'flex';

                    if (isReject) {
                        document.querySelector('.modal-footer').innerHTML = `
                            <button class="btn" onclick="closeApprovalModal()">Cancel</button>
                            <button class="btn btn-danger" onclick="submitRejection()">Reject</button>
                        `;
                    }
                });
        }

        function closeApprovalModal() {
            document.getElementById('approvalModal').style.display = 'none';
        }

        function submitApproval() {
            const approvalId = document.getElementById('approvalId').value;
            const notes = document.getElementById('approvalNotes').value;

            fetch('/api/approve/' + approvalId, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ notes: notes })
            })
            .then(response => response.json())
            .then(data => {
                if (data.status === 'success') {
                    closeApprovalModal();
                    refreshData();
                    alert('Artifact approved successfully!');
                }
            });
        }

        function submitRejection() {
            const approvalId = document.getElementById('approvalId').value;
            const notes = document.getElementById('approvalNotes').value;

            fetch('/api/reject/' + approvalId, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ notes: notes })
            })
            .then(response => response.json())
            .then(data => {
                if (data.status === 'success') {
                    closeApprovalModal();
                    refreshData();
                    alert('Artifact rejected successfully!');
                }
            });
        }

        function openUpdateProjectModal(projectId) {
            const progress = prompt('Enter new progress percentage (0-100):');
            if (progress && !isNaN(progress) && progress >= 0 && progress <= 100) {
                fetch('/api/update_project/' + projectId, {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({ progress: parseFloat(progress) })
                })
                .then(response => response.json())
                .then(data => {
                    if (data.status === 'success') {
                        refreshData();
                        alert('Project updated successfully!');
                    }
                });
            } else if (progress !== null) {
                alert('Please enter a valid percentage (0-100).');
            }
        }
    </script>
</body>
</html>
